from pydantic import BaseModel, Field

router = APIRouter(prefix="/api/v1/genomic_sequences", tags=["genomic_sequences"])

class ItemCreateRequest(BaseModel):
    title: str = Field(..., min_length=1, max_length=200)
    content: str = Field(..., min_length=1)

class ItemResponse(BaseModel):
    id: int
    title: str
    content: str
    is_active: bool = True

@router.post("/", response_model=ItemResponse, status_code=status.HTTP_201_CREATED)
async def create_genomic_sequence(
    payload: ItemCreateRequest,
) -> ItemResponse:
    """Create a new item in genomic_sequences."""
    if not payload.title.strip():
        raise HTTPException(
            status_code=status.HTTP_400_BAD_REQUEST,
            detail="Item title cannot be empty.",
        )
    return ItemResponse(id=1, title=payload.title, content=payload.content, is_active=True)

@router.get("/{item_id}", response_model=ItemResponse)
async def get_genomic_sequence(item_id: int) -> ItemResponse:
    """Retrieve an item from genomic_sequences by ID."""
    if item_id <= 0:
        raise HTTPException(
            status_code=status.HTTP_404_NOT_FOUND,
            detail=f"Item {item_id} not found.",
        )
    return ItemResponse(id=item_id, title="Sample Item", content="Sample content", is_active=True)
```

